node --input-type=module <<'JS'
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import YAML from 'yaml';
const dir='docs/features/FEAT-158-desktop-experts';
const baseline=JSON.parse(fs.readFileSync(dir+'/evidence/phase10-scope-baseline.json','utf8'));
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
for(const record of baseline.historical_evidence) assert.equal(sha(fs.readFileSync(dir+'/'+record.path)),record.sha256,record.path);
const data=YAML.parse(fs.readFileSync(dir+'/feature.yaml','utf8'));
assert.deepEqual(data.must_acceptance.map(ac=>ac.id),['AC-001','AC-002','AC-003','AC-004','AC-005','AC-006','AC-008','AC-009','AC-010']);
assert.equal(data.must_acceptance.filter(ac=>ac.status==='pass').length,8);
assert.deepEqual(data.must_acceptance.filter(ac=>ac.status!=='pass').map(ac=>[ac.id,ac.status]),[['AC-010','pending']]);
for(const ac of data.must_acceptance) assert.equal(ac.status,baseline.previous_must_acceptance.find(old=>old.id===ac.id).status);
assert.equal(data.verification.status,'NOT RUN');
assert.equal(data.verification.real_smoke.status,'NOT RUN');
assert.equal(baseline.previous_verification.real_smoke.status,'FAIL');
for(const name of ['00-feature-brief.md','02-verification.md']) {
const contents=fs.readFileSync(dir+'/'+name,'utf8');
assert(!/^\| (?:T07 \/ )?AC-007 \|/m.test(contents),name);
}
console.log('PASS: 9 active ACs, 8 pass, only AC-010 pending; '+baseline.historical_evidence.length+' historical evidence files byte-identical; historical FAIL retained.');
JS
